I took out the code into a separate file:

``` javascript
var EventEmitter = require('events').EventEmitter;

class Bub extends EventEmitter{
  constructor(config) {
    'use strict';
    this.BASE_URL = 'https://api.telegram.org/bot' + config.token;
    this.TIMEOUT = config.timeout || 864000;
    this.offset = null;
  }
}
```

